EXPLICACOES = {
    'o_que_e_jogos_id': "D - b_dhr_r_wbtbf_vq: b dhr ru `qnqbf['snfrf']['2700']['wbtbf']['vq']`?\n\nB qvpvbanevb `qnqbf['snfrf']['2700']['wbtbf']` grz qhnf punirf\nvzcbegnagrf: 'vq' r 'qngn'. N punir 'vq' thneqn BHGEB qvpvbanevb - cnen\npnqn vq qr wbtb, n SVPUN qryr:\n\n    qnqbf['snfrf']['2700']['wbtbf']['vq']['102094']\n    -> {'qngn': '2018-04-14', 'gvzr1': '9', 'gvzr2': '13',\n        'cynpne1': '0', 'cynpne2': '1', 'rfgnqvb_vq': '116', ...}\n\nBh frwn: n PUNIR ru n vq qb wbtb (hzn fgevat) r b INYBE ru n svpun\npbzcyrgn qryr (qngn, gvzrf, cynpnerf, rfgnqvb, ...). Cbe vffb n erfcbfgn\npregn: hz qvpvbanevb dhr, cnen pnqn vq qr wbtb, thneqn n svpun qryr.\n\nNf bhgenf nygreangvinf:\n  - hzn yvfgn pbz nf vqf qr gbqbf bf wbtbf  REENQB. Yvfgn anb fr vaqrkn\n    cbe punir - fr sbffr yvfgn, `...['wbtbf']['vq']['102094']` anb\n    snevn fragvqb. (Hz `yvfg(...)` rz pvzn qryr ngr qnevn nf vqf, znf\n    ryr ANB ru hzn yvfgn.)\n  - hz qvpvbanevb: cnen pnqn qngn, n yvfgn qr vqf  REENQB. Rffr ru b\n    `['qngn']`, b BHGEB qvpvbanevb qrageb qr `['wbtbf']`.\n  - hzn yvfgn pbz nf qngnf rz dhr ubhir wbtb  REENQB. Nf qngnf zbenz ab\n    `['qngn']`, r pbzb punirf qr hz qvpvbanevb, anb ahzn yvfgn.\n",
    'o_que_e_jogos_data': "D - b_dhr_r_wbtbf_qngn: b dhr ru `qnqbf['snfrf']['2700']['wbtbf']['qngn']`?\n\nRu b BHGEB qvpvbanevb qrageb qr `['wbtbf']`, r ryr thneqn bf wbtbf qr\nHZ QVN cnen b bhgeb:\n\n    qnqbf['snfrf']['2700']['wbtbf']['qngn']['2018-04-14']\n    -> ['102094', '102097', '102101']\n\nBh frwn: n PUNIR ru hzn qngn (hzn fgevat) r b INYBE ru n YVFGN qr vqf\nqbf wbtbf qndhryr qvn. Cbe vffb n erfcbfgn pregn: hz qvpvbanevb dhr,\ncnen pnqn qngn, thneqn n yvfgn qr vqf qbf wbtbf qndhryr qvn.\n\nNf bhgenf nygreangvinf:\n  - hzn yvfgn pbz gbqnf nf qngnf  REENQB. Nf qngnf fnb nf PUNIRF qryr\n    (hz `yvfg(...)` rz pvzn qnevn rynf), znf ryr ANB ru hzn yvfgn.\n  - hz qvpvbanevb: cnen pnqn qngn, n svpun qb wbtb  REENQB. Hzn qngn\n    grz INEVBF wbtbf (n yvfgn npvzn grz 3 vqf); svpun qr wbtb fb\n    rkvfgr cbe vq qr wbtb, ab `['vq']`.\n  - hz qvpvbanevb: cnen pnqn vq qr wbtb, n qngn  REENQB. Rffr ru b\n    pnzvaub vairefb: n qngn svpn QRAGEB qn svpun, ab `['vq']`.\n",
    'placar_e_string': "D - cynpne_r_fgevat: b dhr npbagrpr pbz `0 + cynpne1`?\n\nN svpun qb wbtb 102094 grz `'cynpne1': '0'` - ercner anf NFCNF. B\ncynpne sbv teninqb pbzb FGEVAT, anb pbzb ahzreb. Ahzrebf r fgevatf anb\nfr zvfghenz ahzn fbzn:\n\n    0 + '0'    # GlcrReebe - b clguba anb fnor fbzne ahzreb pbz fgevat\n\nB wrvgb pregb ru genafsbezne b cynpne rz ahzreb nagrf qr fbzne:\n\n    vag(cynpne1)    # '0' -> 0\n\nRu rffr b pbafregb qn nygreangvin pregn.\n\nNf bhgenf nygreangvinf:\n  - shapvban fbmvaub, b clguba pbairegr  REENQB. B clguba anb nqvivaun\n    - ryr erpynzn pbz GlcrReebe.\n  - b pbafregb ru fge(0)  REENQB. Vffb genafsbeznevn b 0 rz fgevat -\n    '0' + '0' whagnevn nf qhnf (qnaqb '00'), r pbagvahn fraqb fgevat,\n    vahgvy cen pbagn.\n  - shapvban, znf qribyir n fgevat '00'  REENQB. Anb qribyir anqn - qn\n    GlcrReebe nagrf.\n\nPhvqnqb ab shgheb: dhnaqb hz inybe irz qr nedhvib (wfba, pfi), ahzrebf\nzhvgnf irmrf purtnz pbzb fgevat. Pbairegre pbz vag()/sybng() nagrf qr\nsnmre pbagn ru hz cnffb dhnfr boevtngbevb.\n",
    'times_do_jogo_102094': "D - gvzrf_qb_wbtb_102094: b cne qr vqf qbf gvzrf qb wbtb 102094.\n\nErfbyiraqb cnffb n cnffb, qr qrageb cen sben:\n\n  1) n svpun qb wbtb 102094:\n\n       qnqbf2018['snfrf']['2700']['wbtbf']['vq']['102094']\n\n     -> {'qngn': '2018-04-14', 'gvzr1': '9', 'gvzr2': '13',\n         'cynpne1': '0', 'cynpne2': '1', 'rfgnqvb_vq': '116', ...}\n\n  2) b gvzr1 (znaqnagr) r b gvzr2 (ivfvgnagr):\n\n       qnqbf2018['snfrf']['2700']['wbtbf']['vq']['102094']['gvzr1']  -> '9'\n       qnqbf2018['snfrf']['2700']['wbtbf']['vq']['102094']['gvzr2']  -> '13'\n\nWhagnaqb ahz cne (n beqrz anb vzcbegn):\n\n    (qnqbf2018['snfrf']['2700']['wbtbf']['vq']['102094']['gvzr1'],\n     qnqbf2018['snfrf']['2700']['wbtbf']['vq']['102094']['gvzr2'])\n\nReebf cerivfvirvf:\n  - Rfdhrpre ['snfrf']['2700'] ab pnzvaub  REENQB. B qvpvbanevb\n    cevapvcny anb grz n punir 'wbtbf' qvergb - qn XrlReebe.\n  - Erfcbaqre bf ABZRF ('Pehmrveb', 'Terzvb')  REENQB. N crethagn ru\n    crynf VQf; bf abzrf zbenz ab qvpvbanevb qr rdhvcrf, anb an svpun.\n  - Erfcbaqre n qngn bh b rfgnqvb qb wbtb  REENQB. B pnzvaub crqvqb\n    ncbagn cnen gvzr1/gvzr2.\n  - Erfcbaqre an beqrz gebpnqn  ANB ru reeb: b cne anb grz beqrz.\n\nCen pbasreve ab sversbk: qvtvgr '102094' ab pnzcb qr svygeb r pbasven\nbf pnzcbf gvzr1 r gvzr2 qn svpun.\n",
    'data_do_jogo_102132': "D - qngn_qb_wbtb_102132: n qngn qb wbtb 102132.\n\nN qngn zben QRAGEB qn svpun qb wbtb:\n\n    qnqbf2018['snfrf']['2700']['wbtbf']['vq']['102132']['qngn']\n    -> '2018-05-06'\n\nReebf cerivfvirvf:\n  - Rfdhrpre b ['qngn'] ab svz  REENQB. Frz ryr n rkcerffnb qribyir n\n    SVPUN vagrven qb wbtb (hz qvpvbanevb), anb n qngn.\n  - Cebphene rz qnqbf2018['snfrf']['2700']['wbtbf']['qngn']  REENQB.\n    Rffr qvpvbanevb thneqn nf qngnf pbzb PUNIRF (qngn -> yvfgn qr\n    wbtbf); n qngn qr HZ wbtb svpn an svpun qryr.\n  - Rfperire n qngn rz bhgeb sbezngb ('06/05/2018')  REENQB. Abf\n    qnqbf ryn irz '2018-05-06' - nab-zrf-qvn, pbz genpb.\n\nCen pbasreve ab sversbk: qvtvgr '102132' ab pnzcb qr svygeb r byur b\npnzcb qngn qn svpun.\n",
    'quantos_jogos_no_ano': "D - dhnagbf_wbtbf_ab_nab: dhnagbf wbtbf b pnzcrbangb grz.\n\nPnqn wbtb grz hzn svpun ab qvpvbanevb ['vq'] - ragnb b ahzreb qr wbtbf\nru b ahzreb qr PUNIRF qryr:\n\n    yra(qnqbf2018['snfrf']['2700']['wbtbf']['vq'])\n    -> 380\n\nReebf cerivfvirvf:\n  - yra ab ['qngn']  REENQB (b reeb znvf snpvy qr pbzrgre ndhv).\n    ['qngn'] thneqn hz wbtb CBE QNGN - fnb 107 punirf, anb 380.\n  - yra an svpun qr hz wbtb  REENQB. ...['vq']['102094'] ru HZ wbtb;\n    yra qryr qnevn dhnagbf pnzcbf n svpun grz.\n  - Erfcbaqre 380 ab puhgr, frz b yra  cnffn ab grfgr, znf b rkrepvpvb\n    crqr n RKCERFFNB - b yra ru b dhr tnenagr dhr ibpr yr n rfgehghen.\n\nCen pbasreve ab sversbk: hfr b pnzcb qr svygeb pbz 'gvzr1' r ercner\ndhr n neiber pbagvahn zbfgenaqb zhvgbf wbtbf - b yra pbagn gbqbf ryrf.\n",
    'quantas_datas_de_jogo': "D - dhnagnf_qngnf_qr_wbtb: dhnagnf QNGNF qr wbtb b pnzcrbangb grz.\n\nPnqn qngn iven hzn PUNIR qb qvpvbanevb ['qngn']:\n\n    yra(qnqbf2018['snfrf']['2700']['wbtbf']['qngn'])\n    -> 107\n\nB pnzcrbangb grz 380 wbtbf, znf rz 107 qvnf qvsreragrf - inevbf wbtbf\nab zrfzb qvn. Cbe vffb bf qbvf ahzrebf fnb qvsreragrf.\n\nReebf cerivfvirvf:\n  - yra ab ['vq']  REENQB (b rfcryub qn dhrfgnb nagrevbe): fnb 380\n    punirf, anb 107.\n  - Pbagne nf qngnf an znb  pnzvaub reenqb. Qrvkn b yra snmre - ryr fb\n    shapvban fr b pnzvaub rfgvire pregb, r b grfgr qrcraqr qryr.\n\nCen pbasreve ab sversbk: noen b wfba r rkcnaqn n frpnb 'qngn' - nf\nqngnf fnb nf punirf qryn.\n",
    'jogos_de_2018_04_14': 'D - wbtbf_qr_2018_04_14: nf vqf qbf wbtbf qr 2018-04-14.\n\nB qvpvbanevb [\'qngn\'] thneqn, cnen pnqn qngn, n YVFGN qr vqf qbf wbtbf\nqndhryr qvn - ragnb n rkcerffnb ru fb b nprffb:\n\n    qnqbf2018[\'snfrf\'][\'2700\'][\'wbtbf\'][\'qngn\'][\'2018-04-14\']\n    -> [\'102094\', \'102097\', \'102101\']\n\nReebf cerivfvirvf:\n  - Cebphene rz [\'vq\']  REENQB. [\'vq\'][\'102094\'] ru n svpun qr HZ\n    wbtb; cen crethagne "dhnvf wbtbf arffr qvn?" b pnzvaub ru b\n    [\'qngn\'].\n  - Rfdhrpre nf nfcnf qn qngn  REENQB. \'2018-04-14\' ru fgevat - frz\n    nfcnf b clguba cebphen hzn inevniry punznqn 2018-04-14 r qn reeb.\n  - Rfperire n yvfgn an znb  cnffn, znf b cbagb ru b nprffb: fr bf\n    qnqbf zhqnerz, n erfcbfgn rfpevgn an znb anb zhqn whagb.\n\nCen pbasreve ab sversbk: qvtvgr \'2018-04-14\' ab pnzcb qr svygeb r irwn\nbf wbtbf qndhryr qvn yvfgnqbf.\n',
    'par_de_ids_a_mao': 'D - cne_qr_vqf_n_znb: n ghcyn qr vqf qbf gvzrf qb wbtb 102099.\n\nB gerpub gr qn n svpun qb wbtb pbz bf pnzcbf dhr vagrerffnz:\n\n    gerpub_wbtb_102099 = {\'gvzr1\': \'5\', \'gvzr2\': \'17\'}\n\nB rahapvnqb crqr n ghcyn zbagnqn pbz RKCERFFNB (yraqb qb qvpvbanevb,\nvthny n shapnb dhr ibpr inv rfperire ybtb qrcbvf):\n\n    (gerpub_wbtb_102099[\'gvzr1\'], gerpub_wbtb_102099[\'gvzr2\'])\n    -> (\'5\', \'17\')\n\nErfcbaqre (\'5\', \'17\') rfpevgb an znb gnzorz cnffn, znf b cbagb ru b\nnprffb - r n beqrz anb vzcbegn: (\'5\', \'17\') r (\'17\', \'5\') inyrz vthny.\n\nReebf cerivfvirvf:\n  - Erfcbaqre pbz bhgeb pnzcb qb gerpub  REENQB. N crethagn ru crynf\n    vqf qbf GVZRF (gvzr1/gvzr2); \'102099\' r n vq qb WBTB, r n qngn/cynpnerf\n    anb grz anqn n ire pbz n erfcbfgn.\n  - Npune dhr n beqrz vzcbegn  ANB ru reeb. B cne anb grz beqrz - znf\n    fr ibpr erfcbaqrh an beqrz gebpnqn, pbagvahn pregb.\n\nCen pbasreve abf qnqbf qr ireqnqr: noen b nab2018.wfba ab sversbk (zrah\nnedhvib > "noeve nedhvib") r qvtvgr \'102099\' ab pnzcb qr svygeb yn qb\ngbcb. N svpun zbfgenqn grz gvzr1 r gvzr2 rkngnzragr nffvz.\n',
    'par_de_nomes_a_mao': "D - cne_qr_abzrf_n_znb: n ghcyn qr abzrf qbf gvzrf qb wbtb 102106.\n\nB gerpub grz qhnf cnegrf - vthny nb zhaqb erny, baqr n svpun qb wbtb\nthneqn nf vqf r b qvpvbanevb qr rdhvcrf thneqn bf abzrf:\n\n    gerpub_wbtb_102106 = {'gvzr1': '695', 'gvzr2': '25'}\n    gerpub_rdhvcrf_102106 = {'695': {'abzr-pbzhz': 'Puncrpbrafr'},\n                             '25':  {'abzr-pbzhz': 'Infpb'}}\n\nB rahapvnqb crqr n ghcyn zbagnqn pbz RKCERFFNB, cnffnaqb crynf qhnf\ncnegrf (r b zrfzb pnzvaub dhr n shapnb abzr_qb_gvzr crepbeer):\n\n  1) b gvzr1 qb wbtb ru b 695 -> gerpub_rdhvcrf_102106['695']\n     ['abzr-pbzhz'] ru 'Puncrpbrafr';\n  2) b gvzr2 ru b 25 -> gerpub_rdhvcrf_102106['25']\n     ['abzr-pbzhz'] ru 'Infpb'.\n\nWhagnaqb ghqb:\n\n    (gerpub_rdhvcrf_102106[gerpub_wbtb_102106['gvzr1']]['abzr-pbzhz'],\n     gerpub_rdhvcrf_102106[gerpub_wbtb_102106['gvzr2']]['abzr-pbzhz'])\n    -> ('Puncrpbrafr', 'Infpb')\n\nErfcbaqre ('Puncrpbrafr', 'Infpb') rfpevgb an znb gnzorz cnffn, znf b\ncbagb ru b nprffb - r n beqrz anb vzcbegn.\n\nReebf cerivfvirvf:\n  - Erfcbaqre pbz nf vqf ('695', '25')  REENQB. N crethagn ru crybf\n    ABZRF; n pnqrvn vq -> abzr ru b pnzvaub dhr n shapnb abzr_qb_gvzr\n    crepbeer (qnqbf['rdhvcrf'][vq]['abzr-pbzhz']).\n  - Gebpne bf abzrf qr yhtne  ANB ru reeb (b cne anb grz beqrz).\n\nCen pbasreve ab sversbk: qvtvgr '102106' ab pnzcb qr svygeb r pbasven\ngvzr1/gvzr2; qrcbvf qvtvgr '695' r '25' cen ire bf abzr-pbzhz.\n",
    'contagem_estadios_a_mao': "D - pbagntrz_rfgnqvbf_n_znb: dhnagnf irmrf pnqn rfgnqvb ncnerpr.\n\nB gerpub:\n\n    gerpub_rfgnqvbf = {\n        '102098': {'rfgnqvb_vq': '72'},\n        '102128': {'rfgnqvb_vq': '72'},\n        '102094': {'rfgnqvb_vq': '116'},\n    }\n\nCnffb n cnffb: b rfgnqvb '72' ncnerpr ab 102098 r ab 102128 (2 irmrf);\nb '116' ncnerpr fb ab 102094 (1 irm). Erfcbfgn: {72: 2, 116: 1} - nf\npunirf cbqrz fre '72'/'116' (fgevat) bh 72/116 (ahzreb), inyr vthny, r\nn beqrz qnf punirf anb vzcbegn.\n\nReebf cerivfvirvf:\n  - Pbagne b '102094' pbzb qb 72  REENQB. B rfgnqvb_vq qryr ru '116'.\n  - Hfne nf vqf qbf WBTBF pbzb punir ({'102098': 1, ...})  REENQB. N\n    crethagn ru crybf RFGNQVBF - nf punirf qb qvpg qr erfcbfgn grz dhr\n    fre rfgnqvb_vq.\n  - Erfcbaqre 3 (b gbgny qr wbtbf)  REENQB. N crethagn ru n pbagntrz\n    CBE rfgnqvb, anb b gbgny qr wbtbf.\n\nCen pbasreve ab sversbk: qvtvgr 'rfgnqvb_vq' ab pnzcb qr svygeb cen ire\ngbqbf bf wbtbf pbz b rfgnqvb qr pnqn hz, r pbasven bf gerf wbtbf npvzn.\n",
    'ids_dos_jogos_do_25_a_mao': "D - vqf_qbf_wbtbf_qb_25_n_znb: bf wbtbf rz dhr b gvzr '25' wbtbh.\n\nB gerpub:\n\n    gerpub_wbtbf_gvzr_25 = {\n        '102098': {'qngn': '2018-04-15', 'gvzr1': '25', 'gvzr2': '4'},\n        '102128': {'qngn': '2018-05-05', 'gvzr1': '25', 'gvzr2': '26'},\n    }\n\nCnffb n cnffb: ahz wbtb, b gvzr wbtn fr ryr ru b gvzr1 BH b gvzr2. B\n'25' ru gvzr1 ab 102098 (pbagen b 4) r gvzr1 ab 102128 (pbagen b 26) -\nragnb bf qbvf wbtbf ragenz. Erfcbfgn: ['102098', '102128'] (n beqrz anb\nvzcbegn).\n\nReebf cerivfvirvf:\n  - Pbagne fb dhnaqb b gvzr ru b gvzr1  REENQB. B wbtb ragen dhnaqb b\n    gvzr wbtn qr pnfn BH sben - grz dhr grfgne bf qbvf ynqbf.\n  - Erfcbaqre pbz bf nqirefnevbf (['4', '26'])  REENQB. N crethagn ru\n    crynf vqf qbf WBTBF, anb crybf gvzrf dhr ryr raseragbh.\n  - Erfcbaqre ['102098'] bh ['102128'] (hz fb)  REENQB. Bf qbvf wbtbf\n    grz b 25 rz pnzcb.\n\nCen pbasreve ab sversbk: qvtvgr '102098' r '102128' ab pnzcb qr svygeb\nr irwn b gvzr1 qr pnqn hz.\n",
    'datas_do_25_a_mao': "D - qngnf_qb_25_n_znb: rz dhr qvnf b gvzr '25' wbtbh.\n\nZrfzb gerpub qn dhrfgnb nagrevbe, ntben byunaqb b pnzcb 'qngn':\n\n    gerpub_wbtbf_gvzr_25 = {\n        '102098': {'qngn': '2018-04-15', 'gvzr1': '25', 'gvzr2': '4'},\n        '102128': {'qngn': '2018-05-05', 'gvzr1': '25', 'gvzr2': '26'},\n    }\n\nB wbtb 102098 npbagrprh rz 2018-04-15; b 102128 rz 2018-05-05. B gvzr\n'25' wbtbh abf qbvf, ragnb n erfcbfgn ru ['2018-04-15', '2018-05-05']\n(n beqrz anb vzcbegn).\n\nReebf cerivfvirvf:\n  - Erfcbaqre pbz nf vqf qbf wbtbf qr abib  REENQB. N crethagn ntben ru\n    crynf QNGNF - pnqn qngn svpn ab pnzcb 'qngn' qn svpun qb wbtb.\n  - Gebpne nf qngnf qr yhtne  ANB ru reeb (n beqrz anb vzcbegn).\n  - Rfperire '2018-04-15' pbz bhgeb sbezngb (rk: '15/04/2018')\n    REENQB. Nf qngnf inb RKNGNZRAGR pbzb rfgnb abf qnqbf, pbz b genpb.\n\nCen pbasreve ab sversbk: qvtvgr '102098' r '102128' ab pnzcb qr svygeb\nr irwn b pnzcb qngn qr pnqn svpun.\n",
    'gols_por_time_a_mao': "D - tbyf_cbe_gvzr_n_znb: dhnagbf tbyf pnqn gvzr srm abf 3 wbtbf.\n\nB gerpub:\n\n    gerpub_tbyf = {\n        '102096': {'gvzr1': '26', 'gvzr2': '76', 'cynpne1': '3', 'cynpne2': '0'},\n        '102098': {'gvzr1': '25', 'gvzr2': '4',  'cynpne1': '2', 'cynpne2': '1'},\n        '102102': {'gvzr1': '6',  'gvzr2': '11', 'cynpne1': '2', 'cynpne2': '1'},\n    }\n\nCnffb n cnffb, wbtb cbe wbtb (cynpne1 inv ceb gvzr1, cynpne2 ceb gvzr2):\n\n  102096: 26 snm 3, 76 snm 0\n  102098: 25 snm 2, 4 snm 1\n  102102: 6 snm 2, 11 snm 1\n\nFbznaqb cbe gvzr: {26: 3, 76: 0, 25: 2, 4: 1, 6: 2, 11: 1}. Nf punirf\ncbqrz fre fgevat bh ahzreb, r n beqrz qnf punirf anb vzcbegn.\n\nReebf cerivfvirvf:\n  - Rfdhrpre b 76 (dhr srm 0 tbyf)  REENQB. Ryr wbtbh, ragnb grz punir\n    an pbagntrz - b inybe 0 grz dhr ncnerpre.\n  - Fbzne bf qbvf cynpnerf ab ZRFZB gvzr  REENQB. cynpne1 ru qb gvzr1,\n    cynpne2 qb gvzr2 - pnqn hz inv ceb frh qbab.\n  - Rfperire bf INYBERF pbzb fgevat ({'26': '3', ...})  REENQB. Arfgn\n    yvfgn, n PUNIR nprvgn '26' bh 26 (inyr vthny), znf b INYBE grz dhr\n    fre b ahzreb zrfzb: {26: 3, ...}.\n\nCen pbasreve ab sversbk: qvtvgr '102096' (bh bf bhgebf qbvf vqf) ab\npnzcb qr svygeb r pbasven bf cynpnerf qr pnqn svpun.\n",
    'time_mais_gols_a_mao': "D - gvzr_znvf_tbyf_n_znb: b gvzr dhr srm znvf tbyf abf 3 wbtbf.\n\nHfn n pbagntrz qn dhrfgnb nagrevbe:\n\n    {26: 3, 76: 0, 25: 2, 4: 1, 6: 2, 11: 1}\n\nDhny punir grz b ZNVBE inybe? B 26 grz 3 tbyf - avathrz cnffn qryr\n(b 25 r b 6 grz 2, bf bhgebf grz zrabf bh mreb). Erfcbfgn: '26'.\n\nReebf cerivfvirvf:\n  - Erfcbaqre pbz hz gvzr dhr grz 2 tbyf (25 bh 6)  REENQB. 'znvf' dhre\n    qvmre b znvbe qn yvfgn - 3 > 2.\n  - Erfcbaqre pbz n PBAGNTRZ (3)  REENQB. N crethagn ru cryn VQ qb\n    gvzr, anb cryb ahzreb qr tbyf.\n  - Erfcbaqre '6'  REENQB (crtnqvaun qr yrvghen: 6 gnzorz grz 2 tbyf,\n    znf b pnzcrnb qb gerpub ru b 26, pbz 3).\n\nCen pbasreve ab sversbk: pbasven bf cynpnerf qbf 3 wbtbf (vqf 102096,\n102098 r 102102) r fbzr an znb - b 26 srpun pbz 3 tbyf.\n",
    'init_contagem': 'D - vavg_pbagntrz: pbzb pevne n pbagntrz vavpvny.\n\nN pbagntrz inv zncrne rfgnqvb -> ahzreb qr wbtbf. B dhr thneqn cnerf\npunir-inybe ru b QVPVBANEVB - r pbzrpnzbf inmvb:\n\n    pbagntrz = {}\n\nNf bhgenf nygreangvinf:\n  - pbagntrz = []  REENQB. Yvfgn thneqn cbfvpbrf, anb cnerf punir-inybe;\n    nyrz qvffb, `pbagntrz[rfgnqvb]` ahzn yvfgn inmvn qn VaqrkReebe.\n  - pbagntrz = 0  REENQB. Ahzreb anb grz pbzb thneqne n pbagntrz cbe\n    rfgnqvb.\n  - pbagntrz = [{}]  REENQB. Hzn yvfgn pbz hz qvpvbanevb qrageb - anb\n    ru b dhr n tragr dhre, r vaqrkne pbz rfgnqvb pbagvahnevn reenqb.\n',
    'percorre_jogos': "D - crepbeer_wbtbf: pbzb crepbeere gbqbf bf wbtbf.\n\nN yvfgn qr wbtbf anb ru hzn yvfgn - ru b qvpvbanevb\n['snfrf']['2700']['wbtbf']['vq'], dhr thneqn pnqn SVPUN ahzn punir (n\nvq qb wbtb). Cen naqne crynf svpunf, hfnzbf .inyhrf():\n\n    sbe wbtb va qnqbf['snfrf']['2700']['wbtbf']['vq'].inyhrf():\n\nNffvz `wbtb` inyr n svpun vagrven (b qvpg pbz qngn, gvzr1, gvzr2,\ncynpnerf, rfgnqvb_vq...). Frz b .inyhrf(), b `sbe` naqnevn crynf PUNIRF\n(nf vqf, fgevatf) - r n yvaun frthvagr (`rfgnqvb = wbtb['rfgnqvb_vq']`)\ndhroenevn, cbedhr fgevat anb grz n punir 'rfgnqvb_vq'.\n\nNf bhgenf nygreangvinf:\n  - sbe wbtb va ...['vq']:  REENQB. Naqn crynf punirf (nf vqf pbzb\n    fgevatf), anb crynf svpunf.\n  - sbe wbtb va ...['wbtbf']:  REENQB. B qvpvbanevb 'wbtbf' grz 3\n    punirf (qngn, ebqnqn, vq) - naqnevn cbe rffrf 3 abzrf, anb crybf\n    380 wbtbf.\n  - sbe wbtb va ...['qngn']:  REENQB. Naqnevn crynf QNGNF (107), anb\n    crybf wbtbf - r pnqn qngn inyr hzn yvfgn qr vqf, anb hzn svpun.\n",
    'pega_estadio': 'D - crtn_rfgnqvb: pbzb crtne b rfgnqvb qb wbtb qn irm.\n\nQrageb qb ynpb, `wbtb` ru n SVPUN qr hz wbtb. B rfgnqvb zben aryn, ab\npnzcb \'rfgnqvb_vq\' (n vq ahzrevpn qb rfgnqvb):\n\n    rfgnqvb = wbtb[\'rfgnqvb_vq\']\n\nNf bhgenf nygreangvinf:\n  - wbtb[\'rfgnqvb\']  REENQB (b znvf genvpbrveb). N svpun grz bf QBVF\n    pnzcbf: \'rfgnqvb\' thneqn b ABZR (\'Zvarvenb\') r \'rfgnqvb_vq\' n vq.\n    Pbagne cbe \'rfgnqvb\' "shapvbanevn" (anb qn reeb), znf nf punirf qb\n    qvpg qr erfcbfgn ivenevnz abzrf - r b grfgr `rfgnqvbf[\'72\']` qnevn\n    XrlReebe.\n  - qnqbf[\'rfgnqvb_vq\']  REENQB. B qvpvbanevb cevapvcny `qnqbf` anb\n    grz n punir \'rfgnqvb_vq\' - qn XrlReebe.\n  - qnqbf[\'snfrf\'][\'2700\'][\'wbtbf\'][\'vq\'][\'rfgnqvb_vq\']  REENQB.\n    Cebphen n punir \'rfgnqvb_vq\' qrageb qb qvpg qr wbtbf - anb rkvfgr\n    (nf punirf qr yn fnb nf vqf qbf wbtbf), r vtaben n svpun `wbtb`\n    dhr n tragr wn grz an znb.\n',
    'por_que_checar': 'D - cbe_dhr_purpne: cbe dhr n purpntrz cerpvfn rkvfgve.\n\nFrz n purpntrz, n yvaun frevn:\n\n    pbagntrz[rfgnqvb] = pbagntrz[rfgnqvb] + 1\n\nAn CEVZRVEN irm dhr hz rfgnqvb ncnerpr, ryr nvaqn anb ru punir qr\npbagntrz. B ynqb QVERVGB (`pbagntrz[rfgnqvb]`) gragn YRE hzn punir dhr\nanb rkvfgr - r yre punir varkvfgragr qn XrlReebe (b zrfzb qb\nntraqn[crffbn] pbz crffbn sben qn ntraqn). Cbe vffb n erfcbfgn pregn: n\ncevzrven irm qn XrlReebe.\n\nNf bhgenf nygreangvinf:\n  - anqn zhqn, shapvban vthny  REENQB. Shapvban fvz, znf fb n cnegve\n    qn FRTHAQN irm qr pnqn rfgnqvb - n cevzrven rfgbhen.\n  - b cebtenzn svpn yragb  REENQB. Anb svpn - dhroen.\n  - pbagn ghqb rz qboeb  REENQB. B reeb npbagrpr nagrf qr dhnydhre\n    pbagn reenqn.\n',
    'como_checar': 'D - pbzb_purpne: pbzb n purpntrz fr rfperir.\n\nN crethagn ru "b rfgnqvb wn ru PUNIR qn pbagntrz?". Nf punirf qr hz\nqvpvbanevb fr crethagnz pbz .xrlf():\n\n    vs rfgnqvb abg va pbagntrz.xrlf():\n\nNf bhgenf nygreangvinf:\n  - vs rfgnqvb abg va pbagntrz.inyhrf():  REENQB. .inyhrf() fnb bf\n    AHZREBF qr pbagntrz (0, 1, 2...). Hz rfgnqvb ahapn inv rfgne yn,\n    ragnb n purpntrz frzcer "qnevn pregb" - r b vavg qr mreb ahapn\n    npbagrprevn (b oht fb ncnerprevn an XrlReebe frthvagr).\n  - vs pbagntrz[rfgnqvb] == 0:  REENQB. Rffn yvaun wn YREVN n punir -\n    r an cevzrven irm n punir anb rkvfgr, XrlReebe nagrf qb grfgr.\n  - vs rfgnqvb abg va qnqbf.xrlf():  REENQB. Purpn ab qvpvbanevb\n    CEVAPVCNY, anb an pbagntrz - b rfgnqvb ahapn inv fre punir yn, r n\n    purpntrz creqr b fragvqb.\n',
    'estadio_novo': 'D - rfgnqvb_abib: b dhr snmre dhnaqb b rfgnqvb nvaqn ANB rfgn an\npbagntrz.\n\nN ybtvpn ru: pevne n punir pbz mreb cen QRCBVF fbzne 1 aryn (cbe vffb b\ncnqenb fr punzn vavg-0-ragnb-vaperzragn):\n\n    pbagntrz[rfgnqvb] = 0\n\nNf bhgenf nygreangvinf:\n  - pbagntrz[rfgnqvb] = 1  REENQB. Chyn b mreb r fbzn 1 rzohgvqb -\n    shapvban CBE NPNFB arfgn yvfgn, znf dhroen b cnqenb (r fr hz qvn b\n    "fbzr 1" ivene "fbzr 2", n cevzrven bpbeerapvn svpnevn reenqn).\n  - pbagntrz.nccraq(rfgnqvb)  REENQB. nccraq ru zrgbqb qr YVFGN;\n    qvpvbanevb anb grz nccraq - qn NggevohgrReebe.\n  - pbagntrz[0] = rfgnqvb  REENQB. Pevn n punir 0 (b ahzreb) inyraqb b\n    rfgnqvb - vairegr ghqb: n punir qrirevn fre b rfgnqvb, anb b 0.\n',
    'incremento_estadios': 'D - vaperzragb_rfgnqvbf: pbzb fbzne 1 an pbagntrz.\n\nN punir wn rkvfgr (b vavg qr mreb ebqbh an cevzrven irm). Ntben n\npbagntrz abin ru n nagvtn znvf 1, thneqnqn qr ibygn an zrfzn punir:\n\n    pbagntrz[rfgnqvb] = pbagntrz[rfgnqvb] + 1\n\nYnqb qvervgb YR n pbagntrz nghny, fbzn 1, r n ngevohvpnb THNEQN an\nzrfzn punir - b cnqenb pynffvpb qr nphzhyne.\n\nNf bhgenf nygreangvinf:\n  - pbagntrz[rfgnqvb] = 1  REENQB. Gbqn irm fboerfperir pbz 1 - n\n    pbagntrz ahapn cnffn qr 1 (gbqb rfgnqvb svpnevn pbz 1).\n  - pbagntrz = pbagntrz + 1  REENQB. Fbzne 1 ab QVPVBANEVB vagrveb anb\n    rkvfgr - qn GlcrReebe.\n  - pbagntrz.nccraq(rfgnqvb)  REENQB. nccraq ru zrgbqb qr YVFGN -\n    NggevohgrReebe.\n',
}
